using System.Security.Claims; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using RaceDay.Api.Data; using RaceDay.Api.DTOs; using RaceDay.Api.Models;
namespace RaceDay.Api.Controllers;
[ApiController,Route("api/results")]
public class ResultsController(RaceDayDbContext db):ControllerBase {
 int UserId=>int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);
 [Authorize(Roles=Roles.Organiser),HttpPost("enrolment/{enrolmentId:int}")] public async Task<IActionResult> Record(int enrolmentId,ResultRequest r){var en=await db.Enrolments.Include(x=>x.Event).Include(x=>x.Result).FirstOrDefaultAsync(x=>x.EnrolmentId==enrolmentId);if(en==null)return NotFound();if(en.Event!.OrganiserId!=UserId)return Forbid();if(en.Result!=null)return Conflict(new{message="A result already exists. Use PUT to update it."});if(r.FinishTime<TimeSpan.Zero)return BadRequest(new{message="Finish time must not be negative."});var result=new Result{EnrolmentId=enrolmentId,FinishTime=r.FinishTime,FinishingPosition=r.FinishingPosition};db.Results.Add(result);await db.SaveChangesAsync();return Created($"/api/results/{result.ResultId}",result);}
 [Authorize(Roles=Roles.Organiser),HttpPut("enrolment/{enrolmentId:int}")] public async Task<IActionResult> Update(int enrolmentId,ResultRequest r){var en=await db.Enrolments.Include(x=>x.Event).Include(x=>x.Result).FirstOrDefaultAsync(x=>x.EnrolmentId==enrolmentId);if(en==null)return NotFound();if(en.Event!.OrganiserId!=UserId)return Forbid();if(en.Result==null)return NotFound();en.Result.FinishTime=r.FinishTime;en.Result.FinishingPosition=r.FinishingPosition;en.Result.RecordedAt=DateTime.UtcNow;await db.SaveChangesAsync();return Ok(en.Result);}
 [Authorize(Roles=Roles.Participant),HttpGet("mine")] public async Task<IActionResult> Mine()=>Ok(await db.Results.Where(r=>r.Enrolment!.ParticipantId==UserId).Include(r=>r.Enrolment).ThenInclude(e=>e!.Event).Include(r=>r.Enrolment).ThenInclude(e=>e!.Category).Select(r=>new{r.ResultId,Event=r.Enrolment!.Event!.Name,EventDate=r.Enrolment.Event.EventDate,Category=r.Enrolment.Category!.Name,r.FinishTime,r.FinishingPosition,r.RecordedAt}).ToListAsync());
 [Authorize(Roles=Roles.Organiser),HttpGet("event/{eventId:int}")] public async Task<IActionResult> ForEvent(int eventId){var e=await db.Events.FindAsync(eventId);if(e==null)return NotFound();if(e.OrganiserId!=UserId)return Forbid();return Ok(await db.Results.Where(r=>r.Enrolment!.EventId==eventId).Include(r=>r.Enrolment).ThenInclude(en=>en!.Participant).Select(r=>new{r.ResultId,r.EnrolmentId,Participant=r.Enrolment!.Participant!.FullName,r.FinishTime,r.FinishingPosition}).OrderBy(r=>r.FinishingPosition).ToListAsync());}
}
